import{z as i,x as c,o as r,c as p,q as l,j as t,D as e,d,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"语言内存模型与 data race","description":"","frontmatter":{"title":"语言内存模型与 data race","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/language-memory-model.md","filePath":"cs/language-memory-model.md","lastUpdated":1791063341000}'),B={name:"cs/language-memory-model.md"};function A(E,a,m,h,u,f){const o=c("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="语言内存模型与-data-race" tabindex="-1">语言内存模型与 data race <a class="header-anchor" href="#语言内存模型与-data-race" aria-label="Permalink to &quot;语言内存模型与 data race&quot;">​</a></h1><div class="epigraph"><p>没有 data race 时，程序等价于某种交错的顺序一致执行。有 race 时，C/C++ 是未定义，Java 仍限制可见性。编译器重排必须遵守 happens-before。</p><footer>—— 据 Adve and Hill；Boehm and Adve, Foundations of the C++ Concurrency Memory Model；Java Memory Model（JSR-133）整理</footer></div><p>上一课<a href="/cs/reflection-metadata">反射</a> 可在运行时改字段，并发更乱。缺口是<strong>语言级内存模型</strong>：什么重排合法，data race 是不是 UB。接<a href="/cs/undefined-behavior-opt">UB 与优化</a> 与组成课一致性，但不重讲总线。WebAssembly 下一课当目标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优化想把 load 提出循环；另一线程在写。无模型则要么禁止优化要么允许乱看。JMM/C++11：原子与锁建立 happens-before。缺口是<strong>编译器合同</strong>，不是硬件 MESI 细节。</p><p>Data race：冲突访问、至少一个写、无排序。C++：UB。Java：不崩型，但值可撕（除 long/double 特殊）——仍几乎不可写。</p><p><span class="marginnote">术语翻译：happens-before 就是跨线程的「可见性承诺」——它说的不是钟表时间上的先后，而是「如果 A happens-before B，A 写过的数据 B 必须能读到」。两个访问只要谁也不向谁做这种承诺、其中还有写，就是 data race。</span></p><h3 id="内存模型不是-gc-写屏障" tabindex="-1">内存模型不是 GC 写屏障 <a class="header-anchor" href="#内存模型不是-gc-写屏障" aria-label="Permalink to &quot;内存模型不是 GC 写屏障&quot;">​</a></h3><p>GC 屏障维持三色；内存模型屏障维持可见性。JIT 可能同一条 store 两件事，概念分开。</p><p><span class="marginnote">Boehm–Adve 2008。JSR-133。Adve–Gharachorloo 综述硬件。本课语言层。不写利用级竞态教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IR：<code>atomic</code> 带序（relaxed/acquire/release/seqcst）。优化：不跨原子乱序普通访问。逃逸到多线程的对象：锁消除要证明无逃逸。</p>',12)),(r(),t(n,null,{default:e(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RACE%5B%22data%20race%22%5D%20--%3E%20C%5B%22C%2B%2B%EF%BC%9AUB%22%5D%0A%20%20RACE%20--%3E%20J%5B%22Java%EF%BC%9A%E5%BC%B1%E4%BF%9D%E8%AF%81%22%5D%0A%20%20SYNC%5B%22%E9%94%81%20%2F%20%E5%8E%9F%E5%AD%90%22%5D%20--%3E%20HB%5B%22happens-before%22%5D%0A%20%20HB%20--%3E%20SC%5B%22DRF%20%E2%87%92%20SC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p>与 fast-math 无关；与并发 GC 的对象发布有关：必须安全发布。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编译器+硬件共同实现模型。<code>volatile</code> 在 Java 与 C 意义不同——点名坑。不要用普通 load 当旗。</p><p>DRF-SC：无 race 则程序员可当顺序一致想。有 race 的 C++ 程序优化可删除看起来「有用」的代码。</p><p><span class="marginnote">直觉类比：release 写像快递「封箱并贴单」，acquire 读像「看到单子才开箱」。配对必须落在同一个变量上——线程 1 release 写 flag，线程 2 acquire 读 flag，开的是同一个箱子，箱里（flag 之前写的普通数据）才保证完整可见；换成 relaxed 读，等于不看单子直接翻包裹，里面可能还是空的。</span></p><p><span class="marginnote">常见误区：初学者常拿 C 的 <code>volatile</code> 当锁用。实际上 C 的 volatile 只告诉编译器「别把这几条访问优化掉或重排到别处」，对 CPU 的乱序和缓存可见性毫无约束；Java 的 volatile 才同时给了原子性、可见性和禁止特定重排。用 C volatile 做线程旗标，在多核机器上就是 data race。</span></p>',6)),(r(),t(n,null,{default:e(()=>[s(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E7%BA%BF%E7%A8%8B1%3A%20%E5%86%99%E6%99%AE%E9%80%9A%E6%95%B0%E6%8D%AE%20x%3D42%22%5D%20--%3E%20R%5B%22release%20%E5%86%99%20flag%3Dtrue%22%5D%0A%20%20R%20--%3E%20L%5B%22%E7%BA%BF%E7%A8%8B2%3A%20acquire%20%E8%AF%BB%E5%88%B0%20flag%3D%3Dtrue%22%5D%0A%20%20L%20--%3E%20S%5B%22%E8%AF%BB%20x%20%E4%BF%9D%E8%AF%81%E7%9C%8B%E5%88%B0%2042%22%5D%0A%20%20L%20--%3E%20RLX%5B%22%E8%8B%A5%E6%94%B9%E7%94%A8%20relaxed%20%E8%AF%BB%20flag%22%5D%0A%20%20RLX%20--%3E%20MAY%5B%22x%20%E5%8F%AF%E8%83%BD%E4%BB%8D%E6%98%AF%E6%97%A7%E5%80%BC%200%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[d(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p>这张图回答的问题：release/acquire 配对到底「传递」了什么。答案是把 flag 之前发生的一切写操作打包对另一个线程可见；relaxed 原子只保证自身是原子的，不携带任何其他数据的可见性，这正是「旗标必须 acquire/release」的原因。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部内存序表。后课默认：优化受内存模型约束。下一课 WebAssembly 作目标：另一 ABI+线性内存。</p><p>也不把模型当经济学博弈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DRF ⇒ 顺序一致交错；C++ race 是 UB。</li><li>原子序限制重排；与 GC 屏障不同。</li><li>锁消除、LICM 必须看逃逸与同步。</li><li>出处：Boehm and Adve；JSR-133；Adve and Hill。</li></ul>',6))])}const g=i(B,[["render",A]]);export{_ as __pageData,g as default};
